return items.map(item => {
  const data = item.json;

  const now = new Date();
  const fechaArchivo = now.getFullYear().toString() +
    String(now.getMonth() + 1).padStart(2, '0') +
    String(now.getDate()).padStart(2, '0') +
    String(now.getHours()).padStart(2, '0');

  const empresa = (data["Nombre de la Empresa o Emprendimiento"] || "SinNombre")
    .trim()
    .replace(/\s+/g, '_')
    .replace(/[^a-zA-Z0-9_áéíóúÁÉÍÓÚñÑ]/g, '');

  return {
    json: {
      nombre: data["Nombre completo"],
      empresa: data["Nombre de la Empresa o Emprendimiento"],
      contacto: data["Número de contacto"],
      correo: data["Correo electrónico"],
      fechaActual: now.toISOString(),
      nombreArchivoPdf: `Diagnostico_${empresa}_${fechaArchivo}_${data.token || ''}`,
      respuestas: {
        P1: data["P1: ¿En qué etapa se encuentra tu proyecto o negocio?"],
        P2: data["P2: ¿A qué sector pertenece tu actividad principal?"],
        P3: data["P3: ¿En qué subsector te ubicas principalmente?"],
        P4: data["P4: ¿Cuántas personas forman parte de tu equipo actualmente?"],
        P5: data["P5: ¿Cuál es su volumen anual de ingresos expresados en dólares?"],
        P6: data["P6 (Gestión Financiera): Cuando revisas tus cuentas a fin de mes, ¿qué suele suceder?"],
        P7: data["P7 (Gestión Comercial): ¿Cómo llegan los clientes a tu negocio?"],
        P8: data["P8 (Gestión de Procesos): Si mañana tuvieras que ausentarte por 15 días, ¿qué pasaría con el negocio?"],
        P9: data["P9 (Gestión Tecnológica): ¿Qué tan \"digital\" es tu operación diaria?"],
        P10: data["P10 (Gestión de Personas): ¿Cómo te sientes respecto a tu equipo de trabajo?"],
        P11: data["P11: ¿Cuál de estas situaciones te quita más energía actualmente?"],
        P12: data["P12 (Dolor Mayor): ¿Cuál es el problema #1 que, si lográramos resolver hoy mismo, cambiaría por completo el rumbo de tu negocio?"]
      }
    }
  };
});

const input = $input.first().json || {};
const raw = typeof input.output === 'string' ? input.output.trim() : '';

const esHtml = /<body[\s>]/i.test(raw) || /<div[\s>]/i.test(raw);

let sharedStyles = '';
let paginatedContent = '';

if (esHtml) {
  const styleMatch = raw.match(/<style[^>]*>([\s\S]*?)<\/style>/i);
  sharedStyles = styleMatch ? styleMatch[1] : '';

  // Preferimos el bloque .container; si no existe, usamos todo el <body>.
  const containerMatch = raw.match(/<div[^>]*class=["'][^"']*container[^"']*["'][^>]*>([\s\S]*?)<\/div>\s*<\/body>/i);
  const bodyMatch = raw.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  let cuerpo = '';
  if (containerMatch) cuerpo = containerMatch[1];
  else if (bodyMatch) cuerpo = bodyMatch[1];
  else cuerpo = raw.replace(/<!DOCTYPE[^>]*>/i, '').replace(/<\/?html[^>]*>/gi, '').replace(/<head[\s\S]*?<\/head>/i, '');

  const sections = cuerpo.split(/(?=<h2|<div[^>]*class=["'][^"']*(?:section-title|section)[^"']*["'])/i);
  paginatedContent = sections
    .filter((s) => s && s.trim())
    .map((section, i, arr) => `
    <div class="page-block" ${i < arr.length - 1 ? 'style="page-break-after: always;"' : ''}>
      ${section}
    </div>
  `).join('');
}

// Respaldo determinista: si la IA no devolvió HTML usable, el informe se arma
// con las respuestas del formulario. Nunca se queda el lead sin documento.
if (!paginatedContent.trim()) {
  const c = $('Code in JavaScript').item.json || {};
  const r = c.respuestas || {};
  const filas = Object.keys(r)
    .map((k) => `<tr><td style="padding:6px 10px;border-bottom:1px solid #dde3ea;width:34%;"><b>${k}</b></td><td style="padding:6px 10px;border-bottom:1px solid #dde3ea;">${String(r[k] || '—')}</td></tr>`)
    .join('');
  sharedStyles = 'body{font-family:Helvetica,Arial,sans-serif;color:#1a1a1a;font-size:11pt;line-height:1.5;} h1{color:#19325A;font-size:20pt;margin:0 0 6px;} .sub{color:#5C6B7E;margin:0 0 20px;} h2{color:#19325A;font-size:14pt;margin:20px 0 8px;}';
  paginatedContent = `
    <div class="page-block">
      <h1>Diagnóstico Empresarial Express</h1>
      <p class="sub">${c.empresa || ''} · ${new Date().toLocaleDateString('es-PE')}</p>
      <h2>Resumen</h2>
      <p>Este documento reúne las respuestas registradas en el Diagnóstico Express. Un consultor de Grupo Empodera revisará el caso y ampliará los hallazgos en la sesión de acompañamiento.</p>
      <h2>Respuestas registradas</h2>
      <table style="border-collapse:collapse;width:100%;">${filas}</table>
    </div>`;
}

const finalHtml = `
<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <title>Resumen Ejecutivo</title>
  <style>
    ${sharedStyles}
    @page { margin: 20mm; }
    .page-block { page-break-inside: avoid; }
  </style>
</head>
<body>
<div class="container">
  ${paginatedContent}
</div>
</body>
</html>`;

items[0].json.html_paginado = finalHtml;
return items;

const input = $input.first().json || {};
const body = input.body || input;
const t = (v) => (typeof v === 'string' ? v.trim() : '');

const campos = body.campos || {};
const nombre = t(body.nombre) || t(campos['Nombre completo']);
const empresa = t(body.empresa) || t(campos['Nombre de la Empresa o Emprendimiento']);
const telefono = t(body.telefono) || t(body.contacto) || t(campos['Número de contacto']);
const correo = (t(body.correo) || t(campos['Correo electrónico'])).toLowerCase();
const respuestas = body.respuestas || {};

const faltan = [];
if (!nombre) faltan.push('nombre');
if (!empresa) faltan.push('empresa');
if (telefono.replace(/\D/g, '').length < 7) faltan.push('telefono');
if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(correo)) faltan.push('correo');

if (faltan.length) return [{ json: { ok: false, faltan } }];

const rnd = () => Math.random().toString(36).slice(2);
const token = (rnd() + rnd() + rnd() + Date.now().toString(36)).replace(/[^a-z0-9]/g, '').slice(0, 40);

return [{
  json: Object.assign({}, campos, {
    'Nombre completo': nombre,
    'Nombre de la Empresa o Emprendimiento': empresa,
    'Número de contacto': telefono,
    'Correo electrónico': correo,
    submittedAt: new Date().toISOString(),
    formMode: 'web',
    ok: true,
    token,
    correo,
    empresa,
    respuestas,
  }),
}];

const q = $('Web Estado').item.json.query || {};
const t = String(q.t || '').trim();
const items = $input.all();
const found = items.some((i) => i.json && i.json.id);

if (!found) {
  return [{ json: { estado: 'procesando', progreso: 45, descarga: '', correo: '', mensaje: '' } }];
}
return [{ json: {
  estado: 'listo',
  progreso: 100,
  descarga: `/api/diagnostico/archivo?t=${t}`,
  correo: '',
  mensaje: '',
} }];

const it = items[0];
const b = it.binary && it.binary.data;
if (b && !/\.pdf$/i.test(b.fileName || '')) {
  b.fileName = (b.fileName || 'diagnostico') + '.pdf';
  b.mimeType = 'application/pdf';
}
return items;

const d = items[0].json || {};
const rnd = () => Math.random().toString(36).slice(2);
const token = (rnd() + rnd() + rnd() + Date.now().toString(36)).replace(/[^a-z0-9]/g, '').slice(0, 40);
items[0].json = Object.assign({}, d, { token, origen: 'form_n8n' });
return items;

